    align-items: center;
    justify-content: center;
    color: var(--white);
    font-size: 1.4rem;
    flex-shrink: 0;
}

.today-card .date-text {
    flex: 1;
}

.today-card .date-text .hijri-date {
    font-family: var(--font-display);
    font-size: 1.15rem;
    font-weight: 700;
    color: var(--green-800);
    margin-bottom: 2px;
}

.today-card .date-text .greg-date {
    font-size: 0.85rem;
    color: var(--gray-500);
}

/* ─── بطاقة التقويم ──────────────────────────────────────── */
.calendar-card {
    background: var(--white);
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-lg);
    overflow: hidden;
    margin-bottom: 20px;
}

/* ─── شريط التنقل ────────────────────────────────────────── */
.nav-bar {
    background: linear-gradient(135deg, var(--green-800), var(--green-700));
    padding: 16px 20px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
}

.nav-bar .nav-btn {
    background: rgba(255,255,255,0.12);
    border: 1px solid rgba(255,255,255,0.2);
    color: var(--white);
    width: 40px;
    height: 40px;
    border-radius: 50%;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.1rem;
    transition: all 0.2s;
}

.nav-bar .nav-btn:hover {
    background: rgba(255,255,255,0.25);
    transform: scale(1.05);
}

.nav-bar .month-info {
    text-align: center;
    flex: 1;
}

.nav-bar .month-title {
    font-family: var(--font-display);
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--white);
}

.nav-bar .gregorian-range {
    font-size: 0.8rem;
    color: rgba(255,255,255,0.7);
    margin-top: 2px;
}

.leap-badge {
    display: none;
    background: var(--gold-500);
    color: var(--green-900);
    font-size: 0.65rem;
    font-weight: 700;
    padding: 2px 8px;
    border-radius: var(--radius-xl);
    margin-right: 8px;
    vertical-align: middle;
}

.today-nav-btn {
    background: rgba(255,255,255,0.12);
    border: 1px solid rgba(255,255,255,0.2);
    color: var(--white);
    padding: 6px 14px;
    border-radius: var(--radius-xl);
    cursor: pointer;
    font-family: var(--font-arabic);
    font-size: 0.78rem;
    transition: all 0.2s;
}

.today-nav-btn:hover {
    background: rgba(255,255,255,0.25);
}

/* ─── رؤوس الأيام ───────────────────────────────────────── */
.day-headers {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    background: var(--green-50);
    border-bottom: 1px solid var(--green-100);
}

.day-header {
    padding: 10px 4px;
    text-align: center;
    font-size: 0.78rem;
    font-weight: 600;
    color: var(--green-700);
}

.day-header:last-child {
    color: var(--green-600);
    background: rgba(39, 166, 120, 0.08);
}

/* ─── شبكة التقويم ───────────────────────────────────────── */
.calendar-grid {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    gap: 1px;
    background: var(--gray-100);
    padding: 1px;
}

.calendar-cell {
    background: var(--white);
    padding: 8px 6px;
    min-height: 62px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 3px;
    cursor: pointer;
    transition: all 0.15s;
    position: relative;
}

.calendar-cell:hover {
    background: var(--green-50);
    z-index: 1;
}

.calendar-cell .hijri-day {
    font-family: var(--font-display);
    font-size: 1.2rem;
    font-weight: 700;
    color: var(--gray-800);
    line-height: 1;
}

.calendar-cell .greg-day {
    font-size: 0.68rem;
    color: var(--gray-400);
    line-height: 1;
}

/* يوم الجمعة */
.calendar-cell:nth-child(7n) {
    background: rgba(39, 166, 120, 0.04);
}

.calendar-cell:nth-child(7n) .hijri-day {
    color: var(--green-600);
}

/* شهر آخر */
.calendar-cell.other-month {
    background: var(--gray-50);
}

.calendar-cell.other-month .hijri-day {
    color: var(--gray-300);
}

.calendar-cell.other-month .greg-day {
    color: var(--gray-300);
}

/* اليوم الحالي */
.calendar-cell.today {
    background: linear-gradient(135deg, var(--green-600), var(--green-500));
    border-radius: var(--radius-sm);
}

.calendar-cell.today .hijri-day {
    color: var(--white);
    font-size: 1.3rem;
}

.calendar-cell.today .greg-day {
    color: rgba(255,255,255,0.75);
}

.calendar-cell.today:hover {
    background: linear-gradient(135deg, var(--green-700), var(--green-600));
}

/* يوم محدد */
.calendar-cell.selected {
    outline: 2px solid var(--gold-500);
    outline-offset: -2px;
    border-radius: var(--radius-sm);
}

/* ─── شريط المعلومات ─────────────────────────────────────── */
.info-bar {
    padding: 12px 20px;
    background: var(--cream);
    border-top: 1px solid var(--gray-200);
    text-align: center;
    font-size: 0.85rem;
    color: var(--gray-600);
    min-height: 44px;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* ─── بطاقة المحوّل ──────────────────────────────────────── */
.converter-card {
    background: var(--white);
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-md);
    overflow: hidden;
    margin-bottom: 20px;
}

.converter-card .card-header {
    background: var(--green-50);
    padding: 14px 20px;
    border-bottom: 1px solid var(--green-100);
    font-family: var(--font-display);
    font-size: 1.1rem;
    font-weight: 700;
    color: var(--green-800);
}

.converter-section {
    padding: 16px 20px;
    border-bottom: 1px solid var(--gray-100);
}

.converter-section:last-child {
    border-bottom: none;
}

.converter-section h3 {
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--green-700);
    margin-bottom: 10px;
}

.input-row {
    display: flex;
    gap: 8px;
    align-items: center;
    flex-wrap: wrap;
}

.input-group {
    display: flex;
    flex-direction: column;
    gap: 3px;
    flex: 1;
    min-width: 70px;
}

.input-group label {
    font-size: 0.7rem;
    color: var(--gray-500);
}

.input-group input {
    font-family: var(--font-arabic);
    font-size: 0.9rem;
    padding: 8px 10px;
    border: 1px solid var(--gray-200);
    border-radius: var(--radius-sm);
    text-align: center;
    color: var(--gray-800);
    background: var(--gray-50);
    transition: border-color 0.2s;
    width: 100%;
    direction: ltr;
}

.input-group input:focus {
    outline: none;
    border-color: var(--green-500);
    background: var(--white);
}

.convert-btn {
    background: linear-gradient(135deg, var(--green-700), var(--green-500));
    color: var(--white);
    border: none;
    padding: 8px 20px;
    border-radius: var(--radius-sm);
    cursor: pointer;
    font-family: var(--font-arabic);
    font-size: 0.82rem;
    font-weight: 600;
    transition: all 0.2s;
    white-space: nowrap;
    align-self: flex-end;
    margin-top: 3px;
}

.convert-btn:hover {
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgba(26, 107, 79, 0.3);
}

.conversion-result {
    margin-top: 10px;
    padding: 10px 14px;
    background: var(--gold-100);
    border-radius: var(--radius-sm);
    font-size: 0.88rem;
    color: var(--gray-700);
    min-height: 40px;
    display: flex;
    align-items: center;
}

.conversion-result:empty {
    display: none;
}

.result-label {
    font-weight: 700;
    color: var(--green-700);
    margin-left: 6px;
}

/* ─── بطاقة المعلومات ────────────────────────────────────── */
.about-card {
    background: var(--white);
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-sm);
    padding: 20px 24px;
    border-right: 3px solid var(--gold-500);
}

.about-card h3 {
    font-family: var(--font-display);
    font-size: 1rem;
    color: var(--green-800);
    margin-bottom: 8px;
}

.about-card p {
    font-size: 0.82rem;
    color: var(--gray-600);
    line-height: 1.8;
    margin-bottom: 8px;
}

.about-card .formula {
    display: inline-block;
    background: var(--gray-100);
    padding: 2px 8px;
    border-radius: var(--radius-sm);
    font-family: 'Courier New', monospace;
    font-size: 0.78rem;
    color: var(--green-700);
    direction: ltr;
}

/* ─── الاستجابة ──────────────────────────────────────────── */
@media (max-width: 600px) {
    .container {
        padding: 16px 10px 32px;
    }

    .header h1 {
        font-size: 1.6rem;
    }

    .header .subtitle {
        font-size: 0.8rem;
    }

    .nav-bar .month-title {
        font-size: 1.2rem;
    }

    .calendar-cell {
        min-height: 50px;
        padding: 6px 3px;
    }

    .calendar-cell .hijri-day {
        font-size: 1rem;
    }

    .calendar-cell .greg-day {
        font-size: 0.6rem;
    }

    .today-card {
        padding: 14px 16px;
        gap: 12px;
    }

    .today-card .date-icon {
        width: 42px;
        height: 42px;
        font-size: 1.1rem;
    }

    .input-row {
        gap: 6px;
    }
}

@media (max-width: 380px) {
    .day-header {
        font-size: 0.65rem;
        padding: 8px 2px;
    }

    .calendar-cell .hijri-day {
        font-size: 0.9rem;
    }
}

