   110→    //  المستوى 1 — التقويم الحسابي الجدولي (التوفيقات الإلهامية)
   111→    // ═══════════════════════════════════════════════════════════
   112→
   113→    const Tabular = (() => {
   114→        function isLeapYear(year) {
   115→            return ((11 * year + 15) % 30) < 11;
   116→        }
   117→
   118→        function daysInMonth(year, month) {
   119→            if (month % 2 === 1) return 30;
   120→            if (month === 12 && isLeapYear(year)) return 30;
   121→            return 29;
   122→        }
   123→
   124→        function daysInYear(year) {
   125→            return isLeapYear(year) ? 355 : 354;
   126→        }
   127→
   128→        function hijriToJDN(year, month, day) {
   129→            return day
   130→                + Math.ceil(29.5 * (month - 1))
   131→                + (year - 1) * 354
   132→                + Math.floor((11 * (year - 1) + 15) / 30)
   133→                + EPOCH_JDN - 1;
   134→        }
   135→
   136→        function jdnToHijri(jdn) {
   137→            const k = jdn - EPOCH_JDN;
   138→            let cycles = Math.floor(k / DAYS_IN_30_YEAR_CYCLE);
   139→            let remainder = k - cycles * DAYS_IN_30_YEAR_CYCLE;
   140→            if (remainder < 0) { cycles--; remainder += DAYS_IN_30_YEAR_CYCLE; }
   141→
   142→            let yc = Math.floor(30 * remainder / DAYS_IN_30_YEAR_CYCLE);
   143→            let ds = yc * 354 + Math.floor((11 * yc + 15) / 30);
   144→            if (ds > remainder) { yc--; ds = yc * 354 + Math.floor((11 * yc + 15) / 30); }
   145→            let dn = (yc + 1) * 354 + Math.floor((11 * (yc + 1) + 15) / 30);
   146→            if (dn <= remainder) { yc++; ds = dn; }
   147→
   148→            const year = cycles * 30 + yc + 1;
   149→            let dayOfYear = remainder - ds;
   150→
   151→            let month = Math.min(Math.ceil((dayOfYear + 1) / 29.5), 12);
   152→            if (month < 1) month = 1;
   153→            let dbm = Math.ceil(29.5 * (month - 1));
   154→            while (dbm > dayOfYear && month > 1) { month--; dbm = Math.ceil(29.5 * (month - 1)); }
   155→
   156→            return { year, month, day: dayOfYear - dbm + 1 };
   157→        }
   158→
   159→        return { isLeapYear, daysInMonth, daysInYear, hijriToJDN, jdnToHijri };
   160→    })();
