   162→    // ═══════════════════════════════════════════════════════════
   163→    //  المستوى 2 — الحساب الفلكي (Jean Meeus, Astronomical Algorithms)
   164→    // ═══════════════════════════════════════════════════════════
   165→
   166→    const Astronomical = (() => {
   167→        /**
   168→         * حساب لحظة الاقتران الفلكي (المحاق / New Moon)
   169→         * بناءً على Jean Meeus, Astronomical Algorithms, Ch. 49
   170→         *
   171→         * المُدخل: k — رقم الاقتران (k=0 عند J2000.0 تقريباً، 2000 يناير 6)
   172→         *   k عدد صحيح = محاق، k+0.5 = بدر
   173→         *
   174→         * المُخرج: JDE (Julian Ephemeris Day) للحظة الاقتران
   175→         */
   176→        function newMoonJDE(k) {
   177→            const T = k / 1236.85;
   178→            const T2 = T * T;
   179→            const T3 = T2 * T;
   180→            const T4 = T3 * T;
   181→
   182→            // التقريب الأولي (Meeus eq. 49.1)
   183→            let JDE = 2451550.09766 + 29.530588861 * k
   184→                + 0.00015437 * T2
   185→                - 0.000000150 * T3
   186→                + 0.00000000073 * T4;
   187→
   188→            // زوايا أساسية (بالدرجات)
   189→            const toRad = Math.PI / 180;
   190→
   191→            // الشذوذ المتوسط للشمس (M)
   192→            const M = 2.5534 + 29.10535670 * k
   193→                - 0.0000014 * T2
   194→                - 0.00000011 * T3;
   195→
   196→            // الشذوذ المتوسط للقمر (M')
   197→            const Mp = 201.5643 + 385.81693528 * k
   198→                + 0.0107582 * T2
   199→                + 0.00001238 * T3
   200→                - 0.000000058 * T4;
   201→
   202→            // حجة خط عرض القمر (F)
   203→            const F = 160.7108 + 390.67050284 * k
   204→                - 0.0016118 * T2
   205→                - 0.00000227 * T3
   206→                + 0.000000011 * T4;
   207→
   208→            // طول العقدة الصاعدة (Omega)
   209→            const Omega = 124.7746 - 1.56375588 * k
   210→                + 0.0020672 * T2
   211→                + 0.00000215 * T3;
   212→
   213→            // المُعامِل E (الانحراف المركزي لمدار الأرض)
   214→            const E = 1 - 0.002516 * T - 0.0000074 * T2;
   215→            const E2 = E * E;
   216→
   217→            const Mr = M * toRad;
   218→            const Mpr = Mp * toRad;
   219→            const Fr = F * toRad;
   220→            const Or = Omega * toRad;
   221→
   222→            // تصحيحات المحاق (Table 49.A في Meeus)
   223→            let correction = 0;
   224→            correction += -0.40720 * Math.sin(Mpr);
   225→            correction +=  0.17241 * E * Math.sin(Mr);
   226→            correction +=  0.01608 * Math.sin(2 * Mpr);
   227→            correction +=  0.01039 * Math.sin(2 * Fr);
   228→            correction +=  0.00739 * E * Math.sin(Mpr - Mr);
   229→            correction += -0.00514 * E * Math.sin(Mpr + Mr);
   230→            correction +=  0.00208 * E2 * Math.sin(2 * Mr);
   231→            correction += -0.00111 * Math.sin(Mpr - 2 * Fr);
   232→            correction += -0.00057 * Math.sin(Mpr + 2 * Fr);
   233→            correction +=  0.00056 * E * Math.sin(2 * Mpr + Mr);
   234→            correction += -0.00042 * Math.sin(3 * Mpr);
   235→            correction +=  0.00042 * E * Math.sin(Mr + 2 * Fr);
   236→            correction +=  0.00038 * E * Math.sin(Mr - 2 * Fr);
   237→            correction += -0.00024 * E * Math.sin(2 * Mpr - Mr);
   238→            correction += -0.00017 * Math.sin(Or);
   239→            correction += -0.00007 * Math.sin(Mpr + 2 * Mr);
   240→            correction +=  0.00004 * Math.sin(2 * Mpr - 2 * Fr);
   241→            correction +=  0.00004 * Math.sin(3 * Mr);
   242→            correction +=  0.00003 * Math.sin(Mpr + Mr - 2 * Fr);
   243→            correction +=  0.00003 * Math.sin(2 * Mpr + 2 * Fr);
   244→            correction += -0.00003 * Math.sin(Mpr + Mr + 2 * Fr);
   245→            correction +=  0.00003 * Math.sin(Mpr - Mr + 2 * Fr);
   246→            correction += -0.00002 * Math.sin(Mpr - Mr - 2 * Fr);
   247→            correction += -0.00002 * Math.sin(3 * Mpr + Mr);
   248→            correction +=  0.00002 * Math.sin(4 * Mpr);
   249→
   250→            JDE += correction;
   251→
   252→            // تصحيحات إضافية (A terms — planetary arguments)
   253→            const A = [];
   254→            A[1]  = 299.77 +  0.107408 * k - 0.009173 * T2;
   255→            A[2]  = 251.88 +  0.016321 * k;
   256→            A[3]  = 251.83 + 26.651886 * k;
   257→            A[4]  = 349.42 + 36.412478 * k;
   258→            A[5]  =  84.66 + 18.206239 * k;
   259→            A[6]  = 141.74 + 53.303771 * k;
   260→            A[7]  = 207.14 +  2.453732 * k;
   261→            A[8]  = 154.84 +  7.306860 * k;
   262→            A[9]  =  34.52 + 27.261239 * k;
   263→            A[10] = 207.19 +  0.121824 * k;
   264→            A[11] = 291.34 +  1.844379 * k;
   265→            A[12] = 161.72 + 24.198154 * k;
   266→            A[13] = 239.56 + 25.513099 * k;
   267→            A[14] = 331.55 +  3.592518 * k;
   268→
   269→            const addCorr = [
   270→                0, 0.000325, 0.000165, 0.000164, 0.000126, 0.000110,
   271→                0.000062, 0.000060, 0.000056, 0.000047, 0.000042,
   272→                0.000040, 0.000037, 0.000035, 0.000023
   273→            ];
   274→
   275→            for (let i = 1; i <= 14; i++) {
   276→                JDE += addCorr[i] * Math.sin(A[i] * toRad);
   277→            }
   278→
   279→            return JDE;
   280→        }
   281→
   282→        /**
   283→         * تحويل JDE → JDN (تقريب اليوم)
   284→         * الشهر الهجري يبدأ عند غروب الشمس بعد المحاق
   285→         * نضيف ~1 يوم تقريباً لأن الهلال لا يُرى إلا بعد الاقتران بـ 15-24 ساعة
   286→         * ثم نأخذ JDN
   287→         */
   288→        function newMoonToMonthStart(jde) {
   289→            // الشهر يبدأ في المساء التالي للاقتران + وقت كافٍ لظهور الهلال
   290→            // تقريب: نضيف يوماً واحداً ثم نأخذ الجزء الصحيح
   291→            return Math.round(jde + 0.5);
   292→        }
   293→
   294→        // ─── ذاكرة مؤقتة لبدايات الشهور ─────────────────────
   295→        const _monthStartCache = {};
   296→
   297→        /**
   298→         * إيجاد قيمة k التقريبية لبداية شهر هجري معين
   299→         * k=0 عند اقتران يناير 2000 تقريباً
   300→         * 1 محرم 1421 ≈ 6 أبريل 2000
   301→         */
   302→        function _approxK(year, month) {
   303→            // عدد الأشهر الهجرية منذ 1 محرم 1 هـ
   304→            const hijriMonths = (year - 1) * 12 + (month - 1);
   305→            // 1 محرم 1 هـ ≈ يوليو 622م
   306→            // k=0 ≈ يناير 2000
   307→            // الفرق بالأشهر القمرية بين الحقبة و J2000:
   308→            // (2000 - 622.5) * 12.3685 ≈ 17038.8 شهر ميلادي
   309→            // لكن بالأشهر القمرية: (2451550.09766 - 1948440) / 29.530588861 ≈ 17038.37
   310→            const epochK = -17038.37;
   311→            return epochK + hijriMonths;
   312→        }
   313→
   314→        /**
   315→         * حساب JDN لبداية شهر هجري معين
   316→         * (أول يوم من الشهر)
   317→         */
   318→        function monthStartJDN(year, month) {
   319→            const key = `${year}-${month}`;
   320→            if (_monthStartCache[key] !== undefined) return _monthStartCache[key];
   321→
   322→            const approxK = _approxK(year, month);
   323→            const k = Math.round(approxK);
   324→
   325→            // نحسب اقتران هذا الشهر والشهر السابق والتالي
   326→            const jde = newMoonJDE(k);
   327→            const jdePrev = newMoonJDE(k - 1);
   328→            const jdeNext = newMoonJDE(k + 1);
   329→
   330→            const jdn = newMoonToMonthStart(jde);
   331→            const jdnPrev = newMoonToMonthStart(jdePrev);
   332→            const jdnNext = newMoonToMonthStart(jdeNext);
   333→
   334→            // نستخدم التقويم الجدولي كمرجع تقريبي للتحقق
   335→            const tabJDN = Tabular.hijriToJDN(year, month, 1);
   336→
   337→            // نختار الأقرب لتقدير التقويم الجدولي (±2 يوم)
   338→            let bestJDN = jdn;
   339→            if (Math.abs(jdnPrev - tabJDN) < Math.abs(bestJDN - tabJDN)) bestJDN = jdnPrev;
   340→            if (Math.abs(jdnNext - tabJDN) < Math.abs(bestJDN - tabJDN)) bestJDN = jdnNext;
   341→
   342→            _monthStartCache[key] = bestJDN;
   343→            return bestJDN;
   344→        }
   345→
   346→        function daysInMonth(year, month) {
   347→            const start = monthStartJDN(year, month);
   348→            const nm = month === 12 ? monthStartJDN(year + 1, 1) : monthStartJDN(year, month + 1);
   349→            return nm - start;
   350→        }
   351→
   352→        function daysInYear(year) {
   353→            return monthStartJDN(year + 1, 1) - monthStartJDN(year, 1);
   354→        }
   355→
   356→        function isLeapYear(year) {
   357→            return daysInYear(year) === 355;
   358→        }
   359→
   360→        function hijriToJDN(year, month, day) {
   361→            return monthStartJDN(year, month) + day - 1;
   362→        }
   363→
   364→        function jdnToHijri(jdn) {
   365→            // تقدير أولي باستخدام الجدولي
   366→            const approx = Tabular.jdnToHijri(jdn);
   367→            let y = approx.year;
   368→            let m = approx.month;
   369→
   370→            // ضبط السنة
   371→            while (monthStartJDN(y + 1, 1) <= jdn) y++;
   372→            while (monthStartJDN(y, 1) > jdn) y--;
   373→
   374→            // ضبط الشهر
   375→            m = 1;
   376→            while (m < 12) {
   377→                const nextStart = (m === 12) ? monthStartJDN(y + 1, 1) : monthStartJDN(y, m + 1);
   378→                if (nextStart <= jdn) m++;
   379→                else break;
   380→            }
   381→
   382→            const d = jdn - monthStartJDN(y, m) + 1;
   383→            return { year: y, month: m, day: d };
   384→        }
   385→
   386→        return { isLeapYear, daysInMonth, daysInYear, hijriToJDN, jdnToHijri, monthStartJDN, newMoonJDE };
   387→    })();
