   454→    function gregorianToJDN(year, month, day) {
   455→        const a = Math.floor((14 - month) / 12);
   456→        const y = year + 4800 - a;
   457→        const m = month + 12 * a - 3;
   458→        return day
   459→            + Math.floor((153 * m + 2) / 5)
   460→            + 365 * y
   461→            + Math.floor(y / 4)
   462→            - Math.floor(y / 100)
   463→            + Math.floor(y / 400)
   464→            - 32045;
   465→    }
   466→
   467→    function jdnToGregorian(jdn) {
   468→        const a = jdn + 32044;
   469→        const b = Math.floor((4 * a + 3) / 146097);
   470→        const c = a - Math.floor(146097 * b / 4);
   471→        const d = Math.floor((4 * c + 3) / 1461);
   472→        const e = c - Math.floor(1461 * d / 4);
   473→        const m = Math.floor((5 * e + 2) / 153);
   474→        return {
   475→            day: e - Math.floor((153 * m + 2) / 5) + 1,
   476→            month: m + 3 - 12 * Math.floor(m / 10),
   477→            year: 100 * b + d - 4800 + Math.floor(m / 10)
   478→        };
   479→    }
