   496→    // ─── بيانات الشهر للعرض ─────────────────────────────────
   497→
   498→    function getMonthData(year, month) {
   499→        const totalDays = daysInMonth(year, month);
   500→        const firstDayJDN = hijriToJDN(year, month, 1);
   501→        const firstDayOfWeek = dayOfWeek(firstDayJDN);
   502→        const todayJDNValue = todayJDN();
   503→        const correction = getCorrection(year, month);
   504→        const cumCorr = _getCumulativeCorrection(year, month);
   505→
   506→        const days = [];
   507→        for (let d = 1; d <= totalDays; d++) {
   508→            const jdn = firstDayJDN + d - 1;
   509→            const greg = jdnToGregorian(jdn);
   510→            days.push({
   511→                hijriDay: d, gregorian: greg,
   512→                dayOfWeek: dayOfWeek(jdn), jdn, isToday: jdn === todayJDNValue
   513→            });
   514→        }
   515→
   516→        // أيام الشهر السابق
   517→        const prevMonth = month === 1 ? 12 : month - 1;
   518→        const prevYear = month === 1 ? year - 1 : year;
   519→        const prevMonthDays = daysInMonth(prevYear, prevMonth);
