   524→            const greg = jdnToGregorian(actualJDN);
   525→            leadingDays.push({
   526→                hijriDay: d, gregorian: greg,
   527→                dayOfWeek: dayOfWeek(actualJDN), jdn: actualJDN,
   528→                isToday: actualJDN === todayJDNValue, isOtherMonth: true
   529→            });
   530→        }
   531→
   532→        // أيام الشهر التالي
   533→        const nextMonth = month === 12 ? 1 : month + 1;
   534→        const nextYear = month === 12 ? year + 1 : year;
   535→        const totalCells = leadingDays.length + totalDays;
   536→        const trailingCount = (7 - (totalCells % 7)) % 7;
   537→        const trailingDays = [];
   538→        for (let d = 1; d <= trailingCount; d++) {
   539→            const actualJDN = hijriToJDN(nextYear, nextMonth, d);
   540→            const greg = jdnToGregorian(actualJDN);
   541→            trailingDays.push({
   542→                hijriDay: d, gregorian: greg,
   543→                dayOfWeek: dayOfWeek(actualJDN), jdn: actualJDN,
   544→                isToday: actualJDN === todayJDNValue, isOtherMonth: true
