   554→        } else if (firstGreg.year === lastGreg.year) {
   555→            gregorianRange = `${GREGORIAN_MONTH_NAMES[firstGreg.month - 1]} – ${GREGORIAN_MONTH_NAMES[lastGreg.month - 1]} ${firstGreg.year}`;
   556→        } else {
   557→            gregorianRange = `${GREGORIAN_MONTH_NAMES[firstGreg.month - 1]} ${firstGreg.year} – ${GREGORIAN_MONTH_NAMES[lastGreg.month - 1]} ${lastGreg.year}`;
