   184→/* ─── شريط التنقل ────────────────────────────────────────── */
   185→.nav-bar {
   186→    background: linear-gradient(135deg, var(--green-800), var(--green-700));
   187→    padding: 16px 20px;
   188→    display: flex;
   189→    align-items: center;
   190→    justify-content: space-between;
   191→    gap: 12px;
   192→}
   193→
   194→.nav-bar .nav-btn {
