   216→    flex: 1;
   217→}
   218→
   219→.nav-bar .month-title {
   220→    font-family: var(--font-display);
   221→    font-size: 1.5rem;
   222→    font-weight: 700;
   223→    color: var(--white);
   224→}
   225→
   226→.nav-bar .gregorian-range {
   227→    font-size: 0.8rem;
   228→    color: rgba(255,255,255,0.7);
   229→    margin-top: 2px;
   230→}
   231→
   232→.leap-badge {
   233→    display: none;
   234→    background: var(--gold-500);
   235→    color: var(--green-900);
   236→    font-size: 0.65rem;
   237→    font-weight: 700;
   238→    padding: 2px 8px;
   239→    border-radius: var(--radius-xl);
   240→    margin-right: 8px;
   241→    vertical-align: middle;
   242→}
   243→
   244→.today-nav-btn {
   245→    background: rgba(255,255,255,0.12);
   246→    border: 1px solid rgba(255,255,255,0.2);
   247→    color: var(--white);
   248→    padding: 6px 14px;
   249→    border-radius: var(--radius-xl);
   250→    cursor: pointer;
   251→    font-family: var(--font-arabic);
   252→    font-size: 0.78rem;
