   271→    font-size: 0.78rem;
   272→    font-weight: 600;
   273→    color: var(--green-700);
   274→}
   275→
   276→.day-header:last-child {
   277→    color: var(--green-600);
   278→    background: rgba(39, 166, 120, 0.08);
   279→}
   280→
   281→/* ─── شبكة التقويم ───────────────────────────────────────── */
   282→.calendar-grid {
   283→    display: grid;
   284→    grid-template-columns: repeat(7, 1fr);
   285→    gap: 1px;
   286→    background: var(--gray-100);
