   289→
   290→.calendar-cell {
   291→    background: var(--white);
   292→    padding: 8px 6px;
   293→    min-height: 62px;
   294→    display: flex;
   295→    flex-direction: column;
   296→    align-items: center;
   297→    justify-content: center;
