/* ═══════════════════════════════════════════════════════════
   التقويم الهجري — التوفيقات الإلهامية
   ═══════════════════════════════════════════════════════════ */

@import url('https://fonts.googleapis.com/css2?family=Amiri:wght@400;700&family=Cairo:wght@300;400;600;700&display=swap');

/* ─── المتغيرات ──────────────────────────────────────────── */
:root {
    --green-900: #0d3b2e;
    --green-800: #14553f;
    --green-700: #1a6b4f;
    --green-600: #1f8060;
    --green-500: #27a678;
    --green-400: #4cc494;
    --green-100: #d4f0e3;
    --green-50:  #eef9f3;

    --gold-600: #b8860b;
    --gold-500: #d4a017;
    --gold-400: #e6b830;
    --gold-300: #f0cd5e;
    --gold-200: #f5dfa0;
    --gold-100: #fdf3d7;

    --cream:     #fefcf5;
    --white:     #ffffff;
    --gray-50:   #f9fafb;
    --gray-100:  #f3f4f6;
    --gray-200:  #e5e7eb;
    --gray-300:  #d1d5db;
    --gray-400:  #9ca3af;
    --gray-500:  #6b7280;
    --gray-600:  #4b5563;
    --gray-700:  #374151;
    --gray-800:  #1f2937;
    --gray-900:  #111827;

    --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
    --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
    --shadow-lg: 0 10px 30px rgba(0,0,0,0.1);

    --radius-sm: 6px;
    --radius-md: 10px;
    --radius-lg: 16px;
    --radius-xl: 24px;

    --font-arabic: 'Cairo', 'Amiri', 'Segoe UI', Tahoma, sans-serif;
    --font-display: 'Amiri', 'Cairo', serif;
}

/* ─── الأساس ─────────────────────────────────────────────── */
*,
*::before,
*::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

html {
    font-size: 16px;
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-arabic);
    background: var(--cream);
    color: var(--gray-800);
    direction: rtl;
    min-height: 100vh;
    line-height: 1.6;
}

/* ─── زخرفة الخلفية ──────────────────────────────────────── */
body::before {
    content: '';
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    height: 320px;
    background: linear-gradient(135deg, var(--green-900) 0%, var(--green-700) 100%);
    z-index: -1;
}

/* ─── الحاوية الرئيسية ───────────────────────────────────── */
.container {
    max-width: 800px;
    margin: 0 auto;
    padding: 24px 16px 48px;
}

/* ─── الرأس ──────────────────────────────────────────────── */
.header {
    text-align: center;
    padding: 32px 16px 40px;
    color: var(--white);
}

.header-icon {
    font-size: 2.5rem;
    margin-bottom: 8px;
    display: block;
}

.header h1 {
    font-family: var(--font-display);
    font-size: 2.2rem;
    font-weight: 700;
    margin-bottom: 6px;
    text-shadow: 0 2px 4px rgba(0,0,0,0.2);
}

.header .subtitle {
    font-size: 0.9rem;
    opacity: 0.85;
    font-weight: 300;
    line-height: 1.8;
}

