}

.result-label {
    font-weight: 700;
    color: var(--green-700);
    margin-left: 6px;
}

/* ─── بطاقة المعلومات ────────────────────────────────────── */
.about-card {
    background: var(--white);
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-sm);
    padding: 20px 24px;
    border-right: 3px solid var(--gold-500);
}

.about-card h3 {
