    .header .subtitle {
        font-size: 0.8rem;
    }

    .nav-bar .month-title {
        font-size: 1.2rem;
    }

    .calendar-cell {
        min-height: 50px;
        padding: 6px 3px;
    }

    .calendar-cell .hijri-day {
