     1→/**
     2→ * التقويم الهجري — محرك متعدد المستويات
     3→ * ═══════════════════════════════════════════════════════════
     4→ * المستوى 1: التقويم الحسابي الجدولي (التوفيقات الإلهامية)
     5→ * المستوى 2: الحساب الفلكي — اقتران القمر (Jean Meeus) [الافتراضي]
     6→ * المستوى 3: تصحيح يدوي من المستخدم (±1 يوم)
     7→ * ═══════════════════════════════════════════════════════════
     8→ */
     9→
    10→const HijriCalendar = (() => {
    11→    // ─── الثوابت المشتركة ───────────────────────────────────
    12→    const EPOCH_JDN = 1948440;
    13→    const DAYS_IN_30_YEAR_CYCLE = 10631;
    14→
    15→    const MONTH_NAMES = [
    16→        'المحرَّم', 'صفر', 'ربيع الأوَّل', 'ربيع الآخِر',
    17→        'جمادى الأولى', 'جمادى الآخِرة', 'رجب', 'شعبان',
    18→        'رمضان', 'شوَّال', 'ذو القَعدة', 'ذو الحِجَّة'
    19→    ];
    20→
    21→    const DAY_NAMES = [
    22→        'السبت', 'الأحد', 'الإثنين', 'الثلاثاء',
    23→        'الأربعاء', 'الخميس', 'الجمعة'
    24→    ];
    25→
    26→    const GREGORIAN_MONTH_NAMES = [
    27→        'يناير', 'فبراير', 'مارس', 'أبريل',
    28→        'مايو', 'يونيو', 'يوليو', 'أغسطس',
    29→        'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'
    30→    ];
    31→
    32→    const MODE_NAMES = {
    33→        tabular: 'حسابي (التوفيقات الإلهامية)',
    34→        astronomical: 'فلكي (اقتران القمر)',
    35→    };
    36→
    37→    const ARABIC_DIGITS = ['٠', '١', '٢', '٣', '٤', '٥', '٦', '٧', '٨', '٩'];
    38→
    39→    function toArabicNumerals(num) {
    40→        return String(num).replace(/\d/g, d => ARABIC_DIGITS[parseInt(d)]);
    41→    }
    42→
    43→    // ─── الحالة ─────────────────────────────────────────────
    44→    let currentMode = 'astronomical'; // الافتراضي: فلكي
    45→    let weekStart = 0; // 0=السبت، 1=الأحد، 2=الإثنين
    46→
    47→    // تصحيحات المستخدم: { "1447-9": +1, "1447-10": -1 }
    48→    // المفتاح = "سنة-شهر"، القيمة = عدد أيام الإزاحة
    49→    let userCorrections = {};
    50→
    51→    function setMode(mode) {
    52→        if (mode === 'tabular' || mode === 'astronomical') {
    53→            currentMode = mode;
    54→        }
    55→    }
    56→
    57→    function getMode() { return currentMode; }
    58→
    59→    // ─── بداية الأسبوع ─────────────────────────────────────
    60→    function setWeekStart(ws) {
    61→        if (ws >= 0 && ws <= 2) weekStart = ws;
    62→    }
    63→
    64→    function getWeekStart() { return weekStart; }
    65→
    66→    function _loadWeekStart() {
    67→        try {
    68→            const v = parseInt(localStorage.getItem('hijri-weekstart'));
    69→            if (v >= 0 && v <= 2) weekStart = v;
    70→        } catch (e) { /* ignore */ }
    71→    }
    72→
    73→    function _saveWeekStart() {
    74→        try { localStorage.setItem('hijri-weekstart', weekStart); }
    75→        catch (e) { /* ignore */ }
    76→    }
    77→
    78→    // ─── رقم الأسبوع في السنة الهجرية ──────────────────────
    79→    // الأسبوع الأول هو الذي يحتوي على 1 محرم
    80→    function weekOfYear(jdn, hijriYear) {
    81→        const muharram1JDN = hijriToJDN(hijriYear, 1, 1);
    82→        // أول يوم بداية أسبوع يسبق أو يساوي 1 محرم
    83→        const muharram1DOW = dayOfWeek(muharram1JDN);
    84→        const offset = (muharram1DOW - weekStart + 7) % 7;
    85→        const firstWeekStart = muharram1JDN - offset;
    86→        return Math.floor((jdn - firstWeekStart) / 7) + 1;
    87→    }
    88→
    89→    // ─── تصحيحات المستخدم ───────────────────────────────────
    90→    function setCorrection(year, month, offsetDays) {
    91→        const key = `${year}-${month}`;
    92→        if (offsetDays === 0) {
    93→            delete userCorrections[key];
    94→        } else {
    95→            userCorrections[key] = offsetDays;
    96→        }
    97→        _saveCorrections();
    98→    }
    99→
   100→    function getCorrection(year, month) {
   101→        const key = `${year}-${month}`;
   102→        return userCorrections[key] || 0;
   103→    }
   104→
   105→    function clearCorrections() {
   106→        userCorrections = {};
   107→        _saveCorrections();
   108→    }
   109→
   110→    function getAllCorrections() {
   111→        return { ...userCorrections };
   112→    }
   113→
   114→    function _saveCorrections() {
   115→        try {
   116→            localStorage.setItem('hijri-corrections', JSON.stringify(userCorrections));
   117→        } catch (e) { /* ignore */ }
   118→    }
   119→
   120→    function _loadCorrections() {
   121→        try {
   122→            const data = localStorage.getItem('hijri-corrections');
   123→            if (data) userCorrections = JSON.parse(data);
   124→        } catch (e) { /* ignore */ }
   125→    }
   126→
   127→    function _loadMode() {
   128→        try {
   129→            const m = localStorage.getItem('hijri-mode');
   130→            if (m === 'tabular' || m === 'astronomical') currentMode = m;
   131→        } catch (e) { /* ignore */ }
   132→    }
   133→
   134→    function _saveMode() {
   135→        try {
   136→            localStorage.setItem('hijri-mode', currentMode);
   137→        } catch (e) { /* ignore */ }
   138→    }
   139→
   140→    // ═══════════════════════════════════════════════════════════
   141→    //  المستوى 1 — التقويم الحسابي الجدولي (التوفيقات الإلهامية)
   142→    // ═══════════════════════════════════════════════════════════
   143→
   144→    const Tabular = (() => {
   145→        function isLeapYear(year) {
   146→            return ((11 * year + 15) % 30) < 11;
   147→        }
   148→
   149→        function daysInMonth(year, month) {
   150→            if (month % 2 === 1) return 30;
   151→            if (month === 12 && isLeapYear(year)) return 30;
   152→            return 29;
   153→        }
   154→
   155→        function daysInYear(year) {
   156→            return isLeapYear(year) ? 355 : 354;
   157→        }
   158→
   159→        function hijriToJDN(year, month, day) {
   160→            return day
   161→                + Math.ceil(29.5 * (month - 1))
   162→                + (year - 1) * 354
   163→                + Math.floor((11 * (year - 1) + 15) / 30)
   164→                + EPOCH_JDN - 1;
   165→        }
   166→
   167→        function jdnToHijri(jdn) {
   168→            const k = jdn - EPOCH_JDN;
   169→            let cycles = Math.floor(k / DAYS_IN_30_YEAR_CYCLE);
   170→            let remainder = k - cycles * DAYS_IN_30_YEAR_CYCLE;
   171→            if (remainder < 0) { cycles--; remainder += DAYS_IN_30_YEAR_CYCLE; }
   172→
   173→            let yc = Math.floor(30 * remainder / DAYS_IN_30_YEAR_CYCLE);
   174→            let ds = yc * 354 + Math.floor((11 * yc + 15) / 30);
   175→            if (ds > remainder) { yc--; ds = yc * 354 + Math.floor((11 * yc + 15) / 30); }
   176→            let dn = (yc + 1) * 354 + Math.floor((11 * (yc + 1) + 15) / 30);
   177→            if (dn <= remainder) { yc++; ds = dn; }
   178→
   179→            const year = cycles * 30 + yc + 1;
   180→            let dayOfYear = remainder - ds;
   181→
   182→            let month = Math.min(Math.ceil((dayOfYear + 1) / 29.5), 12);
   183→            if (month < 1) month = 1;
   184→            let dbm = Math.ceil(29.5 * (month - 1));
   185→            while (dbm > dayOfYear && month > 1) { month--; dbm = Math.ceil(29.5 * (month - 1)); }
   186→
   187→            return { year, month, day: dayOfYear - dbm + 1 };
   188→        }
   189→
   190→        return { isLeapYear, daysInMonth, daysInYear, hijriToJDN, jdnToHijri };
   191→    })();
   192→
   193→    // ═══════════════════════════════════════════════════════════
   194→    //  المستوى 2 — الحساب الفلكي (Jean Meeus, Astronomical Algorithms)
   195→    // ═══════════════════════════════════════════════════════════
   196→
   197→    const Astronomical = (() => {
   198→        /**
   199→         * حساب لحظة الاقتران الفلكي (المحاق / New Moon)
   200→         * بناءً على Jean Meeus, Astronomical Algorithms, Ch. 49
   201→         *
   202→         * المُدخل: k — رقم الاقتران (k=0 عند J2000.0 تقريباً، 2000 يناير 6)
   203→         *   k عدد صحيح = محاق، k+0.5 = بدر
   204→         *
   205→         * المُخرج: JDE (Julian Ephemeris Day) للحظة الاقتران
   206→         */
   207→        function newMoonJDE(k) {
   208→            const T = k / 1236.85;
   209→            const T2 = T * T;
   210→            const T3 = T2 * T;
   211→            const T4 = T3 * T;
   212→
   213→            // التقريب الأولي (Meeus eq. 49.1)
   214→            let JDE = 2451550.09766 + 29.530588861 * k
   215→                + 0.00015437 * T2
   216→                - 0.000000150 * T3
   217→                + 0.00000000073 * T4;
   218→
   219→            // زوايا أساسية (بالدرجات)
   220→            const toRad = Math.PI / 180;
   221→
   222→            // الشذوذ المتوسط للشمس (M)
   223→            const M = 2.5534 + 29.10535670 * k
   224→                - 0.0000014 * T2
   225→                - 0.00000011 * T3;
   226→
   227→            // الشذوذ المتوسط للقمر (M')
   228→            const Mp = 201.5643 + 385.81693528 * k
   229→                + 0.0107582 * T2
   230→                + 0.00001238 * T3
   231→                - 0.000000058 * T4;
   232→
   233→            // حجة خط عرض القمر (F)
   234→            const F = 160.7108 + 390.67050284 * k
   235→                - 0.0016118 * T2
   236→                - 0.00000227 * T3
   237→                + 0.000000011 * T4;
