   265→            correction += -0.00042 * Math.sin(3 * Mpr);
   266→            correction +=  0.00042 * E * Math.sin(Mr + 2 * Fr);
   267→            correction +=  0.00038 * E * Math.sin(Mr - 2 * Fr);
   268→            correction += -0.00024 * E * Math.sin(2 * Mpr - Mr);
