   270→            correction += -0.00007 * Math.sin(Mpr + 2 * Mr);
   271→            correction +=  0.00004 * Math.sin(2 * Mpr - 2 * Fr);
   272→            correction +=  0.00004 * Math.sin(3 * Mr);
   273→            correction +=  0.00003 * Math.sin(Mpr + Mr - 2 * Fr);
   274→            correction +=  0.00003 * Math.sin(2 * Mpr + 2 * Fr);
   275→            correction += -0.00003 * Math.sin(Mpr + Mr + 2 * Fr);
   276→            correction +=  0.00003 * Math.sin(Mpr - Mr + 2 * Fr);
   277→            correction += -0.00002 * Math.sin(Mpr - Mr - 2 * Fr);
   278→            correction += -0.00002 * Math.sin(3 * Mpr + Mr);
   279→            correction +=  0.00002 * Math.sin(4 * Mpr);
