   357→            const jde = newMoonJDE(k);
   358→            const jdePrev = newMoonJDE(k - 1);
   359→            const jdeNext = newMoonJDE(k + 1);
   360→
   361→            const jdn = newMoonToMonthStart(jde);
   362→            const jdnPrev = newMoonToMonthStart(jdePrev);
   363→            const jdnNext = newMoonToMonthStart(jdeNext);
   364→
   365→            // نستخدم التقويم الجدولي كمرجع تقريبي للتحقق
   366→            const tabJDN = Tabular.hijriToJDN(year, month, 1);
   367→
   368→            // نختار الأقرب لتقدير التقويم الجدولي (±2 يوم)
   369→            let bestJDN = jdn;
   370→            if (Math.abs(jdnPrev - tabJDN) < Math.abs(bestJDN - tabJDN)) bestJDN = jdnPrev;
   371→            if (Math.abs(jdnNext - tabJDN) < Math.abs(bestJDN - tabJDN)) bestJDN = jdnNext;
   372→
   373→            _monthStartCache[key] = bestJDN;
   374→            return bestJDN;
   375→        }
   376→
   377→        function daysInMonth(year, month) {
   378→            const start = monthStartJDN(year, month);
