   386→
   387→        function isLeapYear(year) {
   388→            return daysInYear(year) === 355;
   389→        }
   390→
   391→        function hijriToJDN(year, month, day) {
   392→            return monthStartJDN(year, month) + day - 1;
   393→        }
   394→
   395→        function jdnToHijri(jdn) {
