   411→            }
   412→
   413→            const d = jdn - monthStartJDN(y, m) + 1;
   414→            return { year: y, month: m, day: d };
   415→        }
   416→
   417→        return { isLeapYear, daysInMonth, daysInYear, hijriToJDN, jdnToHijri, monthStartJDN, newMoonJDE };
