/* ─── رؤوس الأيام ───────────────────────────────────────── */
.day-headers {
    display: grid;
    grid-template-columns: 42px repeat(7, 1fr);
    background: var(--green-50);
    border-bottom: 1px solid var(--green-100);
}

.day-header {
    padding: 10px 4px;
    text-align: center;
    font-size: 0.78rem;
    font-weight: 600;
    color: var(--green-700);
}

.day-header.week-header {
    font-size: 0.65rem;
    color: var(--gray-400);
    font-weight: 600;
