   215→    // ═══════════════════════════════════════════════════════════
   216→    //  المستوى 2 — الحساب الفلكي (Jean Meeus, Astronomical Algorithms)
   217→    // ═══════════════════════════════════════════════════════════
   218→
   219→    const Astronomical = (() => {
   220→        /**
   221→         * حساب لحظة الاقتران الفلكي (المحاق / New Moon)
   222→         * بناءً على Jean Meeus, Astronomical Algorithms, Ch. 49
   223→         *
   224→         * المُدخل: k — رقم الاقتران (k=0 عند J2000.0 تقريباً، 2000 يناير 6)
   225→         *   k عدد صحيح = محاق، k+0.5 = بدر
   226→         *
   227→         * المُخرج: JDE (Julian Ephemeris Day) للحظة الاقتران
   228→         */
   229→        function newMoonJDE(k) {
   230→            const T = k / 1236.85;
   231→            const T2 = T * T;
   232→            const T3 = T2 * T;
   233→            const T4 = T3 * T;
   234→
   235→            // التقريب الأولي (Meeus eq. 49.1)
   236→            let JDE = 2451550.09766 + 29.530588861 * k
   237→                + 0.00015437 * T2
   238→                - 0.000000150 * T3
   239→                + 0.00000000073 * T4;
   240→
   241→            // زوايا أساسية (بالدرجات)
   242→            const toRad = Math.PI / 180;
   243→
   244→            // الشذوذ المتوسط للشمس (M)
   245→            const M = 2.5534 + 29.10535670 * k
   246→                - 0.0000014 * T2
   247→                - 0.00000011 * T3;
   248→
   249→            // الشذوذ المتوسط للقمر (M')
   250→            const Mp = 201.5643 + 385.81693528 * k
   251→                + 0.0107582 * T2
   252→                + 0.00001238 * T3
   253→                - 0.000000058 * T4;
   254→
   255→            // حجة خط عرض القمر (F)
   256→            const F = 160.7108 + 390.67050284 * k
   257→                - 0.0016118 * T2
   258→                - 0.00000227 * T3
   259→                + 0.000000011 * T4;
   260→
   261→            // طول العقدة الصاعدة (Omega)
   262→            const Omega = 124.7746 - 1.56375588 * k
   263→                + 0.0020672 * T2
   264→                + 0.00000215 * T3;
   265→
   266→            // المُعامِل E (الانحراف المركزي لمدار الأرض)
   267→            const E = 1 - 0.002516 * T - 0.0000074 * T2;
   268→            const E2 = E * E;
   269→
   270→            const Mr = M * toRad;
   271→            const Mpr = Mp * toRad;
   272→            const Fr = F * toRad;
   273→            const Or = Omega * toRad;
   274→
   275→            // تصحيحات المحاق (Table 49.A في Meeus)
   276→            let correction = 0;
   277→            correction += -0.40720 * Math.sin(Mpr);
   278→            correction +=  0.17241 * E * Math.sin(Mr);
   279→            correction +=  0.01608 * Math.sin(2 * Mpr);
   280→            correction +=  0.01039 * Math.sin(2 * Fr);
   281→            correction +=  0.00739 * E * Math.sin(Mpr - Mr);
   282→            correction += -0.00514 * E * Math.sin(Mpr + Mr);
   283→            correction +=  0.00208 * E2 * Math.sin(2 * Mr);
   284→            correction += -0.00111 * Math.sin(Mpr - 2 * Fr);
   285→            correction += -0.00057 * Math.sin(Mpr + 2 * Fr);
   286→            correction +=  0.00056 * E * Math.sin(2 * Mpr + Mr);
   287→            correction += -0.00042 * Math.sin(3 * Mpr);
   288→            correction +=  0.00042 * E * Math.sin(Mr + 2 * Fr);
   289→            correction +=  0.00038 * E * Math.sin(Mr - 2 * Fr);
   290→            correction += -0.00024 * E * Math.sin(2 * Mpr - Mr);
   291→            correction += -0.00017 * Math.sin(Or);
   292→            correction += -0.00007 * Math.sin(Mpr + 2 * Mr);
   293→            correction +=  0.00004 * Math.sin(2 * Mpr - 2 * Fr);
   294→            correction +=  0.00004 * Math.sin(3 * Mr);
   295→            correction +=  0.00003 * Math.sin(Mpr + Mr - 2 * Fr);
   296→            correction +=  0.00003 * Math.sin(2 * Mpr + 2 * Fr);
   297→            correction += -0.00003 * Math.sin(Mpr + Mr + 2 * Fr);
   298→            correction +=  0.00003 * Math.sin(Mpr - Mr + 2 * Fr);
   299→            correction += -0.00002 * Math.sin(Mpr - Mr - 2 * Fr);
   300→            correction += -0.00002 * Math.sin(3 * Mpr + Mr);
   301→            correction +=  0.00002 * Math.sin(4 * Mpr);
   302→
   303→            JDE += correction;
   304→
   305→            // تصحيحات إضافية (A terms — planetary arguments)
   306→            const A = [];
   307→            A[1]  = 299.77 +  0.107408 * k - 0.009173 * T2;
   308→            A[2]  = 251.88 +  0.016321 * k;
   309→            A[3]  = 251.83 + 26.651886 * k;
   310→            A[4]  = 349.42 + 36.412478 * k;
   311→            A[5]  =  84.66 + 18.206239 * k;
   312→            A[6]  = 141.74 + 53.303771 * k;
   313→            A[7]  = 207.14 +  2.453732 * k;
   314→            A[8]  = 154.84 +  7.306860 * k;
   315→            A[9]  =  34.52 + 27.261239 * k;
   316→            A[10] = 207.19 +  0.121824 * k;
   317→            A[11] = 291.34 +  1.844379 * k;
   318→            A[12] = 161.72 + 24.198154 * k;
   319→            A[13] = 239.56 + 25.513099 * k;
   320→            A[14] = 331.55 +  3.592518 * k;
   321→
   322→            const addCorr = [
   323→                0, 0.000325, 0.000165, 0.000164, 0.000126, 0.000110,
   324→                0.000062, 0.000060, 0.000056, 0.000047, 0.000042,
   325→                0.000040, 0.000037, 0.000035, 0.000023
   326→            ];
   327→
   328→            for (let i = 1; i <= 14; i++) {
   329→                JDE += addCorr[i] * Math.sin(A[i] * toRad);
   330→            }
   331→
   332→            return JDE;
   333→        }
   334→
   335→        /**
   336→         * تحويل JDE → JDN (تقريب اليوم)
   337→         * الشهر الهجري يبدأ عند غروب الشمس بعد المحاق
   338→         * نضيف ~1 يوم تقريباً لأن الهلال لا يُرى إلا بعد الاقتران بـ 15-24 ساعة
   339→         * ثم نأخذ JDN
   340→         */
   341→        function newMoonToMonthStart(jde) {
   342→            // الشهر يبدأ في المساء التالي للاقتران + وقت كافٍ لظهور الهلال
   343→            // تقريب: نضيف يوماً واحداً ثم نأخذ الجزء الصحيح
   344→            return Math.round(jde + 0.5);
   345→        }
   346→
   347→        // ─── ذاكرة مؤقتة لبدايات الشهور ─────────────────────
   348→        const _monthStartCache = {};
   349→
   350→        /**
   351→         * إيجاد قيمة k التقريبية لبداية شهر هجري معين
   352→         * k=0 عند اقتران يناير 2000 تقريباً
   353→         * 1 محرم 1421 ≈ 6 أبريل 2000
   354→         */
   355→        function _approxK(year, month) {
   356→            // عدد الأشهر الهجرية منذ 1 محرم 1 هـ
   357→            const hijriMonths = (year - 1) * 12 + (month - 1);
   358→            // 1 محرم 1 هـ ≈ يوليو 622م
   359→            // k=0 ≈ يناير 2000
   360→            // الفرق بالأشهر القمرية بين الحقبة و J2000:
   361→            // (2000 - 622.5) * 12.3685 ≈ 17038.8 شهر ميلادي
   362→            // لكن بالأشهر القمرية: (2451550.09766 - 1948440) / 29.530588861 ≈ 17038.37
   363→            const epochK = -17038.37;
   364→            return epochK + hijriMonths;
   365→        }
   366→
   367→        /**
   368→         * حساب JDN لبداية شهر هجري معين
   369→         * (أول يوم من الشهر)
   370→         */
   371→        function monthStartJDN(year, month) {
   372→            const key = `${year}-${month}`;
   373→            if (_monthStartCache[key] !== undefined) return _monthStartCache[key];
   374→
   375→            const approxK = _approxK(year, month);
   376→            const k = Math.round(approxK);
   377→
   378→            // نحسب اقتران هذا الشهر والشهر السابق والتالي
   379→            const jde = newMoonJDE(k);
   380→            const jdePrev = newMoonJDE(k - 1);
   381→            const jdeNext = newMoonJDE(k + 1);
   382→
   383→            const jdn = newMoonToMonthStart(jde);
   384→            const jdnPrev = newMoonToMonthStart(jdePrev);
   385→            const jdnNext = newMoonToMonthStart(jdeNext);
   386→
   387→            // نستخدم التقويم الجدولي كمرجع تقريبي للتحقق
   388→            const tabJDN = Tabular.hijriToJDN(year, month, 1);
   389→
   390→            // نختار الأقرب لتقدير التقويم الجدولي (±2 يوم)
   391→            let bestJDN = jdn;
   392→            if (Math.abs(jdnPrev - tabJDN) < Math.abs(bestJDN - tabJDN)) bestJDN = jdnPrev;
   393→            if (Math.abs(jdnNext - tabJDN) < Math.abs(bestJDN - tabJDN)) bestJDN = jdnNext;
   394→
   395→            _monthStartCache[key] = bestJDN;
   396→            return bestJDN;
   397→        }
   398→
   399→        function daysInMonth(year, month) {
   400→            const start = monthStartJDN(year, month);
   401→            const nm = month === 12 ? monthStartJDN(year + 1, 1) : monthStartJDN(year, month + 1);
   402→            return nm - start;
   403→        }
   404→
   405→        function daysInYear(year) {
   406→            return monthStartJDN(year + 1, 1) - monthStartJDN(year, 1);
   407→        }
   408→
   409→        function isLeapYear(year) {
   410→            return daysInYear(year) === 355;
   411→        }
   412→
   413→        function hijriToJDN(year, month, day) {
   414→            return monthStartJDN(year, month) + day - 1;
   415→        }
   416→
   417→        function jdnToHijri(jdn) {
   418→            // تقدير أولي باستخدام الجدولي
   419→            const approx = Tabular.jdnToHijri(jdn);
   420→            let y = approx.year;
   421→            let m = approx.month;
   422→
   423→            // ضبط السنة
   424→            while (monthStartJDN(y + 1, 1) <= jdn) y++;
   425→            while (monthStartJDN(y, 1) > jdn) y--;
   426→
   427→            // ضبط الشهر
   428→            m = 1;
   429→            while (m < 12) {
   430→                const nextStart = (m === 12) ? monthStartJDN(y + 1, 1) : monthStartJDN(y, m + 1);
   431→                if (nextStart <= jdn) m++;
   432→                else break;
   433→            }
   434→
   435→            const d = jdn - monthStartJDN(y, m) + 1;
   436→            return { year: y, month: m, day: d };
   437→        }
   438→
   439→        return { isLeapYear, daysInMonth, daysInYear, hijriToJDN, jdnToHijri, monthStartJDN, newMoonJDE };
   440→    })();
