   442→    // ═══════════════════════════════════════════════════════════
   443→    //  الواجهة الموحدة — تدير المستويات والتصحيحات
   444→    // ═══════════════════════════════════════════════════════════
   445→
   446→    function _engine() {
   447→        return currentMode === 'tabular' ? Tabular : Astronomical;
