   450→    /**
   451→     * حساب إزاحة التصحيح لشهر معين
   452→     * التصحيح يسري من نقطة التطبيق فصاعداً:
   453→     * إذا صحّح المستخدم شهراً، فكل الشهور من هذه النقطة تتأثر
   454→     */
   455→    function _getCumulativeCorrection(year, month) {
   456→        let total = 0;
   457→        const keys = Object.keys(userCorrections).sort();
   458→        for (const key of keys) {
   459→            const [cy, cm] = key.split('-').map(Number);
   460→            // التصحيح يسري على هذا الشهر وكل ما بعده
   461→            if (cy < year || (cy === year && cm <= month)) {
   462→                total += userCorrections[key];
   463→            }
   464→        }
   465→        return total;
   466→    }
