   468→    // ─── الدوال العامة الموحدة ───────────────────────────────
   469→
   470→    function isLeapYear(year) { return _engine().isLeapYear(year); }
   471→
   472→    function daysInMonth(year, month) { return _engine().daysInMonth(year, month); }
   473→
   474→    function daysInYear(year) { return _engine().daysInYear(year); }
   475→
   476→    function hijriToJDN(year, month, day) {
   477→        const baseJDN = _engine().hijriToJDN(year, month, day);
   478→        return baseJDN + _getCumulativeCorrection(year, month);
   479→    }
   480→
   481→    function jdnToHijri(jdn) {
   482→        // البحث العكسي: نحتاج لإيجاد التاريخ الهجري الذي يعطي هذا الـ JDN
   483→        // نبدأ بتقدير بدون تصحيح
   484→        const approx = _engine().jdnToHijri(jdn);
   485→
   486→        // نتحقق مع التصحيح
   487→        let y = approx.year, m = approx.month, d = approx.day;
   488→
   489→        // نعدّل: JDN الفعلي = JDN الأساسي + correction
   490→        // إذن JDN الأساسي = JDN - correction
   491→        const corr = _getCumulativeCorrection(y, m);
   492→        const adjustedJDN = jdn - corr;
   493→        const result = _engine().jdnToHijri(adjustedJDN);
   494→
   495→        // تحقق نهائي: قد يتغير التصحيح بتغير الشهر
   496→        const corr2 = _getCumulativeCorrection(result.year, result.month);
   497→        if (corr2 !== corr) {
   498→            const result2 = _engine().jdnToHijri(jdn - corr2);
   499→            return result2;
   500→        }
   501→
   502→        return result;
   503→    }
   504→
   505→    // ─── تحويل ميلادي ↔ JDN ──────────────────────────────────
   506→
   507→    function gregorianToJDN(year, month, day) {
   508→        const a = Math.floor((14 - month) / 12);
   509→        const y = year + 4800 - a;
   510→        const m = month + 12 * a - 3;
   511→        return day
   512→            + Math.floor((153 * m + 2) / 5)
   513→            + 365 * y
   514→            + Math.floor(y / 4)
   515→            - Math.floor(y / 100)
   516→            + Math.floor(y / 400)
   517→            - 32045;
   518→    }
   519→
   520→    function jdnToGregorian(jdn) {
   521→        const a = jdn + 32044;
   522→        const b = Math.floor((4 * a + 3) / 146097);
   523→        const c = a - Math.floor(146097 * b / 4);
   524→        const d = Math.floor((4 * c + 3) / 1461);
   525→        const e = c - Math.floor(1461 * d / 4);
   526→        const m = Math.floor((5 * e + 2) / 153);
   527→        return {
   528→            day: e - Math.floor((153 * m + 2) / 5) + 1,
   529→            month: m + 3 - 12 * Math.floor(m / 10),
   530→            year: 100 * b + d - 4800 + Math.floor(m / 10)
   531→        };
   532→    }
   533→
   534→    function hijriToGregorian(y, m, d) { return jdnToGregorian(hijriToJDN(y, m, d)); }
   535→    function gregorianToHijri(y, m, d) { return jdnToHijri(gregorianToJDN(y, m, d)); }
   536→
   537→    function dayOfWeek(jdn) { return ((jdn % 7) + 2) % 7; }
   538→
   539→    function todayHijri() {
   540→        const now = new Date();
   541→        return gregorianToHijri(now.getFullYear(), now.getMonth() + 1, now.getDate());
   542→    }
   543→
   544→    function todayJDN() {
   545→        const now = new Date();
   546→        return gregorianToJDN(now.getFullYear(), now.getMonth() + 1, now.getDate());
   547→    }
   548→
   549→    // ─── بيانات الشهر للعرض ─────────────────────────────────
   550→
   551→    function getMonthData(year, month) {
   552→        const totalDays = daysInMonth(year, month);
   553→        const firstDayJDN = hijriToJDN(year, month, 1);
   554→        const firstDayOfWeek = dayOfWeek(firstDayJDN);
   555→        const todayJDNValue = todayJDN();
   556→        const correction = getCorrection(year, month);
   557→        const cumCorr = _getCumulativeCorrection(year, month);
   558→
   559→        const days = [];
   560→        for (let d = 1; d <= totalDays; d++) {
   561→            const jdn = firstDayJDN + d - 1;
   562→            const greg = jdnToGregorian(jdn);
   563→            days.push({
   564→                hijriDay: d, gregorian: greg,
   565→                dayOfWeek: dayOfWeek(jdn), jdn, isToday: jdn === todayJDNValue
   566→            });
   567→        }
   568→
   569→        // عدد أيام البادئة حسب بداية الأسبوع المختارة
   570→        const leadingCount = (firstDayOfWeek - weekStart + 7) % 7;
   571→
   572→        // أيام الشهر السابق
   573→        const prevMonth = month === 1 ? 12 : month - 1;
   574→        const prevYear = month === 1 ? year - 1 : year;
   575→        const prevMonthDays = daysInMonth(prevYear, prevMonth);
   576→        const leadingDays = [];
   577→        for (let i = leadingCount - 1; i >= 0; i--) {
   578→            const d = prevMonthDays - i;
   579→            const actualJDN = hijriToJDN(prevYear, prevMonth, d);
   580→            const greg = jdnToGregorian(actualJDN);
   581→            leadingDays.push({
   582→                hijriDay: d, gregorian: greg,
   583→                dayOfWeek: dayOfWeek(actualJDN), jdn: actualJDN,
   584→                isToday: actualJDN === todayJDNValue, isOtherMonth: true
   585→            });
   586→        }
   587→
   588→        // أيام الشهر التالي
   589→        const nextMonth = month === 12 ? 1 : month + 1;
   590→        const nextYear = month === 12 ? year + 1 : year;
   591→        const totalCells = leadingDays.length + totalDays;
   592→        const trailingCount = (7 - (totalCells % 7)) % 7;
   593→        const trailingDays = [];
   594→        for (let d = 1; d <= trailingCount; d++) {
   595→            const actualJDN = hijriToJDN(nextYear, nextMonth, d);
   596→            const greg = jdnToGregorian(actualJDN);
   597→            trailingDays.push({
   598→                hijriDay: d, gregorian: greg,
   599→                dayOfWeek: dayOfWeek(actualJDN), jdn: actualJDN,
   600→                isToday: actualJDN === todayJDNValue, isOtherMonth: true
   601→            });
   602→        }
   603→
   604→        // النطاق الميلادي
   605→        const firstGreg = jdnToGregorian(firstDayJDN);
   606→        const lastGreg = jdnToGregorian(firstDayJDN + totalDays - 1);
   607→        let gregorianRange;
   608→        if (firstGreg.month === lastGreg.month && firstGreg.year === lastGreg.year) {
   609→            gregorianRange = `${GREGORIAN_MONTH_NAMES[firstGreg.month - 1]} ${firstGreg.year}`;
   610→        } else if (firstGreg.year === lastGreg.year) {
   611→            gregorianRange = `${GREGORIAN_MONTH_NAMES[firstGreg.month - 1]} – ${GREGORIAN_MONTH_NAMES[lastGreg.month - 1]} ${firstGreg.year}`;
   612→        } else {
   613→            gregorianRange = `${GREGORIAN_MONTH_NAMES[firstGreg.month - 1]} ${firstGreg.year} – ${GREGORIAN_MONTH_NAMES[lastGreg.month - 1]} ${lastGreg.year}`;
   614→        }
   615→
   616→        // إضافة رقم الأسبوع لكل يوم
   617→        const allDays = [...leadingDays, ...days, ...trailingDays];
   618→        allDays.forEach(day => {
   619→            const hDate = jdnToHijri(day.jdn);
   620→            day.weekNumber = weekOfYear(day.jdn, hDate.year);
   621→        });
   622→
   623→        // ترتيب رؤوس الأيام حسب بداية الأسبوع
   624→        const orderedDayNames = [];
   625→        for (let i = 0; i < 7; i++) {
   626→            orderedDayNames.push(DAY_NAMES[(weekStart + i) % 7]);
   627→        }
   628→
   629→        return {
   630→            year, month,
   631→            monthName: MONTH_NAMES[month - 1],
   632→            totalDays,
   633→            isLeapYear: isLeapYear(year),
   634→            firstDayOfWeek,
   635→            gregorianRange,
   636→            correction,
   637→            cumulativeCorrection: cumCorr,
   638→            mode: currentMode,
   639→            weekStart,
   640→            orderedDayNames,
   641→            days: allDays
   642→        };
   643→    }
