    function t(key) { return (_UI[currentLang] && _UI[currentLang][key]) || _UI.ar[key] || key; }

    function setLang(lang) { if (lang === 'ar' || lang === 'en') currentLang = lang; }
    function getLang() { return currentLang; }
    function _loadLang() {
