    ' '.repeat(COL.gap) +
    pad(astStr + astMark, COL.result) +
    padLeft(fmtDiff(astroDiff), COL.diff)
  );
}

console.log('  ' + THIN.substring(2));
console.log('  * = differs from expected reference date');
console.log('');

// ═══════════════════════════════════════════════════════════
//  Summary Statistics
// ═══════════════════════════════════════════════════════════

const total = testCases.length;
